232→// StartSession starts an interactive session and registers it for pane
233→// capture in artifacts. Returns nil if the agent does not support interactive
234→// mode. The session is closed automatically during test cleanup.
235→func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
