248→// WaitFor waits for a pattern in the interactive session's pane and logs the
249→// pane content to ConsoleLog after the wait completes (success or failure).
250→func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
