  3→package agents
  4→
  5→import (
  6→	"context"
  7→	"errors"
  8→	"fmt"
  9→	"os"
 10→	"os/exec"
 11→	"strings"
 12→	"syscall"
 13→	"time"
 14→)
 15→
 16→func init() {
 17→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "kiro" {
 18→		return
 19→	}
 20→	if _, err := exec.LookPath("kiro-cli"); err != nil {
 21→		return
 22→	}
 23→	Register(&Kiro{})
 24→	// Kiro uses Amazon Q API which may have rate limits
 25→	RegisterGate("kiro", 1)
 26→}
 27→
 28→// Kiro implements the Agent interface for Amazon's Kiro CLI.
 29→type Kiro struct{}
 30→
 31→func (k *Kiro) Name() string               { return "kiro" }
 32→func (k *Kiro) Binary() string             { return "kiro-cli" }
 33→func (k *Kiro) EntireAgent() string        { return "kiro" }
 34→func (k *Kiro) PromptPattern() string      { return `❯` }
 35→func (k *Kiro) TimeoutMultiplier() float64 { return 1.5 }
 36→
 37→func (k *Kiro) IsTransientError(out Output, _ error) bool {
 38→	combined := out.Stdout + out.Stderr
 39→	for _, p := range []string{"overloaded", "rate limit", "503", "529", "throttl"} {
 40→		if strings.Contains(strings.ToLower(combined), p) {
 41→			return true
 42→		}
 43→	}
 44→	return false
 45→}
 46→
 47→func (k *Kiro) Bootstrap() error {
 48→	// kiro-cli uses Amazon Q / Builder ID auth.
 49→	// On CI, ensure the user is logged in; locally, auth is handled by the desktop app.
 50→	if os.Getenv("CI") == "" {
 51→		return nil
 52→	}
 53→	// Verify login status — fail fast if not authenticated.
 54→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
 55→	defer cancel()
 56→	cmd := exec.CommandContext(ctx, "kiro-cli", "whoami")
 57→	if out, err := cmd.CombinedOutput(); err != nil {
 58→		return fmt.Errorf("kiro-cli auth check failed (run `kiro-cli login`): %s", out)
 59→	}
 60→	return nil
 61→}
 62→
 63→func (k *Kiro) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 64→	cfg := &runConfig{}
 65→	for _, o := range opts {
 66→		o(cfg)
 67→	}
 68→
 69→	args := []string{"chat", "--no-interactive", "-a", prompt}
 70→	if cfg.Model != "" {
 71→		args = []string{"chat", "--no-interactive", "-a", "--model", cfg.Model, prompt}
 72→	}
 73→
 74→	cmd := exec.CommandContext(ctx, k.Binary(), args...)
 75→	cmd.Dir = dir
 76→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
 77→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
 78→	cmd.Cancel = func() error {
 79→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
 80→	}
 81→	cmd.WaitDelay = 5 * time.Second
 82→
 83→	var stdout, stderr strings.Builder
 84→	cmd.Stdout = &stdout
 85→	cmd.Stderr = &stderr
 86→
 87→	err := cmd.Run()
 88→	exitCode := 0
 89→	if err != nil {
 90→		exitErr := &exec.ExitError{}
 91→		if errors.As(err, &exitErr) {
 92→			exitCode = exitErr.ExitCode()
 93→		} else {
 94→			exitCode = -1
 95→		}
 96→	}
 97→
 98→	displayArgs := []string{"chat", "--no-interactive", "-a", fmt.Sprintf("%q", prompt)}
 99→	return Output{
100→		Command:  k.Binary() + " " + strings.Join(displayArgs, " "),
101→		Stdout:   stdout.String(),
102→		Stderr:   stderr.String(),
103→		ExitCode: exitCode,
104→	}, err
105→}
106→
107→func (k *Kiro) StartSession(ctx context.Context, dir string) (Session, error) {
108→	name := fmt.Sprintf("kiro-test-%d", time.Now().UnixNano())
109→	s, err := NewTmuxSession(name, dir, nil, k.Binary(), "chat", "-a")
110→	if err != nil {
111→		return nil, err
112→	}
113→
114→	// Wait for the prompt indicator
115→	if _, err := s.WaitFor(`❯`, 15*time.Second); err != nil {
116→		_ = s.Close()
117→		return nil, fmt.Errorf("waiting for kiro startup prompt: %w", err)
118→	}
119→	s.stableAtSend = ""
120→
121→	return s, nil
122→}
