 43→	if !force {
 44→		if existing, readErr := os.ReadFile(hooksPath); readErr == nil { //nolint:gosec // path constructed from repo root
 45→			var file kiroHooksFile
 46→			if json.Unmarshal(existing, &file) == nil && k.allHooksPresent(file, localDev) {
 47→				return 0, nil
 48→			}
