 55→	} else {
 56→		cmdPrefix = "entire hooks kiro "
 57→	}
 58→
 59→	file := kiroHooksFile{
 60→		AgentSpawn:       []kiroHookEntry{{Command: cmdPrefix + HookNameAgentSpawn}},
 61→		UserPromptSubmit: []kiroHookEntry{{Command: cmdPrefix + HookNameUserPromptSubmit}},
 62→		PreToolUse:       []kiroHookEntry{{Command: cmdPrefix + HookNamePreToolUse}},
 63→		PostToolUse:      []kiroHookEntry{{Command: cmdPrefix + HookNamePostToolUse}},
 64→		Stop:             []kiroHookEntry{{Command: cmdPrefix + HookNameStop}},
 65→	}
 66→
 67→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
 68→		return 0, fmt.Errorf("failed to create .kiro/agents directory: %w", err)
 69→	}
 70→
 71→	output, err := jsonutil.MarshalIndentWithNewline(file, "", "  ")
 72→	if err != nil {
 73→		return 0, fmt.Errorf("failed to marshal hooks config: %w", err)
 74→	}
 75→
 76→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
 77→		return 0, fmt.Errorf("failed to write hooks config: %w", err)
 78→	}
 79→
 80→	return 5, nil
 81→}
