142→		hookCommandExists(file.PreToolUse, cmdPrefix+HookNamePreToolUse) &&
143→		hookCommandExists(file.PostToolUse, cmdPrefix+HookNamePostToolUse) &&
144→		hookCommandExists(file.Stop, cmdPrefix+HookNameStop)
145→}
