219→func (s *RepoState) logPromptResult(out agents.Output) {
220→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
221→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
222→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
223→}
