225→// Git runs a git command in the repo and logs it to ConsoleLog.
226→func (s *RepoState) Git(t *testing.T, args ...string) {
227→	t.Helper()
228→	s.ConsoleLog.WriteString("> git " + strings.Join(args, " ") + "\n")
229→	Git(t, s.Dir, args...)
