284→	out, err := json.MarshalIndent(settings, "", "  ")
285→	if err != nil {
286→		t.Fatalf("marshal settings: %v", err)
287→	}
288→	if err := os.WriteFile(path, out, 0o644); err != nil {
289→		t.Fatalf("write settings: %v", err)
