293→// Git runs a git command in the given directory and fails the test if it
294→// returns a non-zero exit code.
295→func Git(t *testing.T, dir string, args ...string) {
296→	t.Helper()
297→
298→	cmd := exec.Command("git", args...)
299→	if dir != "" {
300→		cmd.Dir = dir
301→	}
302→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
303→
304→	out, err := cmd.CombinedOutput()
305→	if err != nil {
306→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
307→	}
308→}
