333→// NewCheckpointCommits returns the SHAs of commits added to the
334→// entire/checkpoints/v1 branch since the test was set up, oldest first.
335→func NewCheckpointCommits(t *testing.T, s *RepoState) []string {
336→	t.Helper()
337→
338→	log := GitOutput(t, s.Dir, "log", "--reverse", "--format=%H", s.CheckpointBefore+"..entire/checkpoints/v1")
339→	if log == "" {
340→		return nil
341→	}
342→	return strings.Split(log, "\n")
343→}
