370→// ReadCheckpointMetadata reads the checkpoint-level metadata.json from the
371→// tip of the checkpoint branch for the given checkpoint ID.
372→func ReadCheckpointMetadata(t *testing.T, dir string, checkpointID string) CheckpointMetadata {
373→	t.Helper()
374→
375→	path := CheckpointPath(checkpointID) + "/metadata.json"
376→	blob := "entire/checkpoints/v1:" + path
377→
378→	raw := GitOutput(t, dir, "show", blob)
379→
380→	var meta CheckpointMetadata
381→	if err := json.Unmarshal([]byte(raw), &meta); err != nil {
382→		t.Fatalf("unmarshal checkpoint metadata from %s: %v", blob, err)
383→	}
384→
385→	return meta
386→}
