388→// ReadSessionMetadata reads a session's metadata.json from the tip of the
389→// checkpoint branch for the given checkpoint ID and session index.
390→func ReadSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int) SessionMetadata {
391→	t.Helper()
392→
393→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
394→	blob := "entire/checkpoints/v1:" + path
395→
396→	raw := GitOutput(t, dir, "show", blob)
397→
398→	var meta SessionMetadata
399→	if err := json.Unmarshal([]byte(raw), &meta); err != nil {
400→		t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
401→	}
402→
403→	return meta
