	if env := os.Getenv("E2E_AGENT"); env != "" && env != "kiro" {
		return
	}
	if _, err := exec.LookPath("kiro-cli"); err != nil {
		return
	}
	Register(&Kiro{})
	// Kiro uses Amazon Q API which may have rate limits
	RegisterGate("kiro", 1)
}

