  1→// Package kiro implements the Agent interface for Amazon's Kiro CLI.
  2→package kiro
  3→
  4→import (
  5→	"context"
  6→	"encoding/json"
  7→	"errors"
  8→	"fmt"
  9→	"os"
 10→	"os/exec"
 11→	"path/filepath"
 12→	"runtime"
 13→	"strings"
