	if err := s.Send(prompt); err != nil {
		return Output{}, fmt.Errorf("sending prompt to kiro: %w", err)
	}

	// Wait for "Credits:" which only appears after the agent finishes a response.
	// More reliable than PromptPattern for single-prompt mode since it uniquely
	// identifies response completion without needing to distinguish echoed input.
	content, err := s.WaitFor(`Credits:`, timeout)
	exitCode := 0
	if err != nil {
		exitCode = -1
	}

	return Output{
		Command:  k.Binary() + " " + strings.Join(args, " ") + " " + fmt.Sprintf("%q", prompt),
		Stdout:   content,
		ExitCode: exitCode,
	}, err
}

func (k *Kiro) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("kiro-test-%d", time.Now().UnixNano())
	s, err := NewTmuxSession(name, dir, nil, k.Binary(), "chat", "-a", "--agent", "entire")
	if err != nil {
		return nil, err
	}

	// Wait for the prompt indicator — kiro-cli TUI shows "!>" in trust-all mode
	if _, err := s.WaitFor(k.PromptPattern(), 15*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for kiro startup prompt: %w", err)
	}
	s.stableAtSend = ""

	return &KiroSession{TmuxSession: s}, nil
}

// KiroSession wraps TmuxSession for Kiro's interactive sessions.
// After Send, WaitFor is redirected to "Credits:" to avoid matching
// the echoed "!>" prompt pattern in the input line.
type KiroSession struct {
	*TmuxSession
}

func (s *KiroSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
	// For initial waits (before any Send), use the original pattern.
	// After a Send, redirect to "Credits:" because the echoed input line
	// (e.g., "[entire] 3% !> now commit it") contains "!>" which would
	// prematurely match the prompt pattern. "Credits:" only appears after
	// the agent finishes responding, making it a reliable completion marker.
	if s.stableAtSend != "" {
		return s.TmuxSession.WaitFor(`Credits:`, timeout)
	}
	return s.TmuxSession.WaitFor(pattern, timeout)
}

worktreePath, err := paths.WorktreeRoot(ctx)
if err != nil {
	return nil //nolint:nilerr // Hook must be silent on failure
}

// Find all active sessions for this worktree
// We match by worktree (not BaseCommit) because the user may have made
// intermediate commits without entering new prompts, causing HEAD to diverge
sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
if err != nil || len(sessions) == 0 {
	// No active sessions or error listing - silently skip (hooks must be resilient)
	logging.Debug(logCtx, "prepare-commit-msg: no active sessions",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
	)
	return nil //nolint:nilerr // Intentional: hooks must be silent on failure
}

// Fast path: when an agent is committing, skip content detection and
// interactive prompts. Detected in two cases:
//   1. No TTY — the agent runs shell commands non-interactively (Claude Code, Gemini).
//   2. ACTIVE session with no transcript path — the agent uses deferred transcript
//      persistence (e.g., Kiro's SQLite isn't available during the turn). The commit
//      must be from the agent since no transcript means no Stop hook has fired yet.
// In both cases, the agent can't respond to interactive prompts.
for _, state := range sessions {
	if state.Phase.IsActive() && (!hasTTY() || state.TranscriptPath == "") {
		return s.addTrailerForAgentCommit(logCtx, commitMsgFile, state, source)
	}
}

// Check if any session has new content to condense
sessionsWithContent := s.filterSessionsWithNewContent(ctx, repo, sessions)

if len(sessionsWithContent) == 0 {
	// No new content — no trailer needed
	logging.Debug(logCtx, "prepare-commit-msg: no content to link",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.Int("sessions_found", len(sessions)),
	)
	return nil
}

// Read current commit message
content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
if err != nil {
	return nil //nolint:nilerr // Hook must be silent on failure
}

message := string(content)

// Check if trailer already exists (ParseCheckpoint validates format, so found==true means valid)
if existingCpID, found := trailers.ParseCheckpoint(message); found {
	// Trailer already exists (e.g., amend) - keep it
	logging.Debug(logCtx, "prepare-commit-msg: trailer already exists",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.String("existing_checkpoint_id", existingCpID.String()),
	)

