// Fast path: when an agent is committing, skip content detection and
// interactive prompts. Detected in two cases:
//   1. No TTY — the agent runs shell commands non-interactively (Claude Code, Gemini).
//   2. ACTIVE session with no transcript path — the agent uses deferred transcript
//      persistence (e.g., Kiro's SQLite isn't available during the turn). The commit
//      must be from the agent since no transcript means no Stop hook has fired yet.
// In both cases, the agent can't respond to interactive prompts.
for _, state := range sessions {
	if state.Phase.IsActive() && (!hasTTY() || state.TranscriptPath == "") {
		return s.addTrailerForAgentCommit(logCtx, commitMsgFile, state, source)
	}
}

