// KiroSession wraps TmuxSession for Kiro's interactive sessions.
// After Send, WaitFor is redirected to "Credits:" to avoid matching
// the echoed "!>" prompt pattern in the input line.
type KiroSession struct {
	*TmuxSession
}

func (s *KiroSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
	// For initial waits (before any Send), use the original pattern.
	// After a Send, redirect to "Credits:" because the echoed input line
	// (e.g., "[entire] 3% !> now commit it") contains "!>" which would
	// prematurely match the prompt pattern. "Credits:" only appears after
	// the agent finishes responding, making it a reliable completion marker.
	if s.stableAtSend != "" {
		return s.TmuxSession.WaitFor(`Credits:`, timeout)
	}
	return s.TmuxSession.WaitFor(pattern, timeout)
}

input.new_string:
// KiroSession wraps TmuxSession for Kiro's interactive sessions.
// After Send, WaitFor waits for a NEW "Credits:" line to appear, avoiding
// false matches on the echoed "!>" prompt or old "Credits:" from prior turns.
type KiroSession struct {
	*TmuxSession
	creditsCount int // Credits: occurrences at time of last Send
}

func (s *KiroSession) Send(input string) error {
	// Snapshot current Credits: count so WaitFor can detect a new one.
	s.creditsCount = strings.Count(s.Capture(), "Credits:")
	return s.TmuxSession.Send(input)
}

func (s *KiroSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
	// For initial waits (before any Send), use the original pattern ("!>").
	if s.stableAtSend == "" {
		return s.TmuxSession.WaitFor(pattern, timeout)
	}
	// After a Send, wait for a NEW "Credits:" line. The echoed input contains
	// "!>" (e.g., "[entire] 3% !> now commit it") which would prematurely match
	// the prompt pattern. Old "Credits:" lines from prior turns may still be
	// visible in the scrollback, so we count occurrences.
	deadline := time.Now().Add(timeout)
	var matchedAt time.Time
	var lastStable string
	for time.Now().Before(deadline) {
		content := s.Capture()
		if strings.Count(content, "Credits:") <= s.creditsCount {
			matchedAt = time.Time{}
			lastStable = ""
			time.Sleep(pollInterval)
			continue
		}
		stable := stableContent(content)
		if stable != lastStable {
			matchedAt = time.Now()
			lastStable = stable
			time.Sleep(pollInterval)
			continue
		}
		if !matchedAt.IsZero() && time.Since(matchedAt) >= settleTime {
			return content, nil
		}
		time.Sleep(pollInterval)
	}
	content := s.Capture()
	return content, fmt.Errorf("timed out waiting for new Credits: after %s\n--- pane content ---\n%s\n--- end pane content ---", timeout, content)
}

