package types //nolint:revive // types is fine when used outside this package

// AgentName is the registry key type for agents (e.g., "claude-code", "gemini").
type AgentName string

// AgentType is the display name type stored in metadata/trailers (e.g., "Claude Code", "Gemini CLI").
type AgentType string

// unrelated to the agent's recent changes.
//
// This handles the scenario where the agent commits mid-session before Stop.
func (s *ManualCommitStrategy) sessionHasNewContentFromLiveTranscript(ctx context.Context, repo *git.Repository, state *SessionState) (bool, error) {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	modifiedFiles, ok := s.extractNewModifiedFilesFromLiveTranscript(ctx, state)
	if !ok || len(modifiedFiles) == 0 {
		// Fallback for agents with deferred transcript persistence (e.g., Kiro's SQLite-based
		// transcript isn't available during the turn). If the session is ACTIVE and has no
		// transcript path, any staged files are likely agent work. This mirrors the no-TTY
		// fast path logic and PostCommit's unconditional hasNew=true for ACTIVE sessions.
		if state.Phase.IsActive() && state.TranscriptPath == "" {
			stagedFiles := getStagedFiles(repo)
			if len(stagedFiles) > 0 {
				logging.Debug(logCtx, "live transcript check: ACTIVE session without transcript, trusting staged files",
					slog.String("session_id", state.SessionID),
					slog.Int("staged_files", len(stagedFiles)),
				)
				return true, nil
			}
		}
		return false, nil
	}

	logging.Debug(logCtx, "live transcript check: found file modifications",
		slog.String("session_id", state.SessionID),
		slog.Int("modified_files", len(modifiedFiles)),
	)

