 48→			}
 49→		}
 50→	}
 51→
 52→	var cmdPrefix string
 53→	if localDev {
 54→		cmdPrefix = "go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks kiro "
 55→	} else {
 56→		cmdPrefix = "entire hooks kiro "
 57→	}
 58→
 59→	file := kiroAgentFile{
 60→		Name: "entire",
 61→		// Include all default Kiro tools so the agent profile doesn't restrict them.
 62→		Tools: []string{
 63→			"read", "write", "shell", "grep", "glob",
 64→			"aws", "report", "introspect", "knowledge",
 65→			"thinking", "todo", "delegate",
 66→		},
 67→		Hooks: kiroHooks{
 68→			AgentSpawn:       []kiroHookEntry{{Command: cmdPrefix + HookNameAgentSpawn}},
 69→			UserPromptSubmit: []kiroHookEntry{{Command: cmdPrefix + HookNameUserPromptSubmit}},
 70→			PreToolUse:       []kiroHookEntry{{Command: cmdPrefix + HookNamePreToolUse}},
 71→			PostToolUse:      []kiroHookEntry{{Command: cmdPrefix + HookNamePostToolUse}},
 72→			Stop:             []kiroHookEntry{{Command: cmdPrefix + HookNameStop}},
 73→		},
 74→	}
 75→
 76→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
 77→		return 0, fmt.Errorf("failed to create .kiro/agents directory: %w", err)
 78→	}
 79→
 80→	output, err := jsonutil.MarshalIndentWithNewline(file, "", "  ")
 81→	if err != nil {
 82→		return 0, fmt.Errorf("failed to marshal hooks config: %w", err)
 83→	}
 84→
 85→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
 86→		return 0, fmt.Errorf("failed to write hooks config: %w", err)
 87→	}
 88→
 89→	return 5, nil
 90→}
