 92→// UninstallHooks removes the Entire hooks config file.
 93→func (k *KiroAgent) UninstallHooks(ctx context.Context) error {
 94→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 95→	if err != nil {
 96→		worktreeRoot = "."
 97→	}
 98→
 99→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
100→	if err := os.Remove(hooksPath); err != nil && !os.IsNotExist(err) {
101→		return fmt.Errorf("failed to remove hooks config: %w", err)
102→	}
103→	return nil
104→}
