106→// AreHooksInstalled checks if Entire hooks are installed.
107→func (k *KiroAgent) AreHooksInstalled(ctx context.Context) bool {
108→	worktreeRoot, err := paths.WorktreeRoot(ctx)
109→	if err != nil {
110→		worktreeRoot = "."
111→	}
112→
113→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
114→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
115→	if err != nil {
116→		return false
117→	}
118→
119→	var file kiroAgentFile
120→	if err := json.Unmarshal(data, &file); err != nil {
121→		return false
122→	}
123→
124→	return hasEntireHook(file.Hooks.AgentSpawn) ||
125→		hasEntireHook(file.Hooks.UserPromptSubmit) ||
126→		hasEntireHook(file.Hooks.Stop)
127→}
