129→// GetSupportedHooks returns the hook types Kiro supports.
130→func (k *KiroAgent) GetSupportedHooks() []agent.HookType {
131→	return []agent.HookType{
132→		agent.HookSessionStart,
133→		agent.HookUserPromptSubmit,
134→		agent.HookPreToolUse,
135→		agent.HookPostToolUse,
136→		agent.HookStop,
137→	}
138→}
