140→func allHooksPresent(hooks kiroHooks, localDev bool) bool {
141→	var cmdPrefix string
142→	if localDev {
143→		cmdPrefix = "go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go hooks kiro "
144→	} else {
145→		cmdPrefix = "entire hooks kiro "
146→	}
147→
148→	return hookCommandExists(hooks.AgentSpawn, cmdPrefix+HookNameAgentSpawn) &&
149→		hookCommandExists(hooks.UserPromptSubmit, cmdPrefix+HookNameUserPromptSubmit) &&
150→		hookCommandExists(hooks.PreToolUse, cmdPrefix+HookNamePreToolUse) &&
151→		hookCommandExists(hooks.PostToolUse, cmdPrefix+HookNamePostToolUse) &&
152→		hookCommandExists(hooks.Stop, cmdPrefix+HookNameStop)
153→}
154→
155→func hookCommandExists(entries []kiroHookEntry, command string) bool {
156→	for _, entry := range entries {
157→		if entry.Command == command {
158→			return true
159→		}
160→	}
161→	return false
162→}
163→
164→func isEntireHook(command string) bool {
165→	for _, prefix := range entireHookPrefixes {
166→		if strings.HasPrefix(command, prefix) {
167→			return true
168→		}
169→	}
170→	return false
171→}
172→
173→func hasEntireHook(entries []kiroHookEntry) bool {
174→	for _, entry := range entries {
175→		if isEntireHook(entry.Command) {
176→			return true
177→		}
178→	}
179→	return false
180→}
