521→func TestInstallHooks_PreservesUnknownHookTypes(t *testing.T) {
522→	tempDir := t.TempDir()
523→	t.Chdir(tempDir)
524→
525→	// Create settings with a hook type we don't handle (Notification is a real Claude Code hook type)
