579→	if err := json.Unmarshal(rawHooks["SubagentStop"], &subagentStopMatchers); err != nil {
580→		t.Fatalf("failed to parse SubagentStop hooks: %v", err)
581→	}
582→	if len(subagentStopMatchers) != 1 {
583→		t.Errorf("SubagentStop matchers = %d, want 1", len(subagentStopMatchers))
584→	}
585→	if len(subagentStopMatchers) > 0 {
586→		if subagentStopMatchers[0].Matcher != ".*" {
587→			t.Errorf("SubagentStop matcher = %q, want %q", subagentStopMatchers[0].Matcher, ".*")
588→		}
589→		if len(subagentStopMatchers[0].Hooks) > 0 {
590→			if subagentStopMatchers[0].Hooks[0].Command != "echo subagent stopped" {
591→				t.Errorf("SubagentStop hook command = %q, want %q",
592→					subagentStopMatchers[0].Hooks[0].Command, "echo subagent stopped")
593→			}
594→		}
595→	}
596→
597→	// Verify our hooks were also installed
598→	if _, ok := rawHooks["Stop"]; !ok {
599→		t.Errorf("Stop hook should have been installed")
600→	}
